ctle = serdes.CTLE("SymbolTime", 100e-12, "SampleInterval", 6.25e-12, ...
    "Mode", 2, "WaveType", "Impulse", ...
    "DCGain", 0:-1:-26, "PeakingGain", 0:26, "PeakingFrequency", 11e9);
impulseOut = ctle(impulseIn);

ffe = serdes.FFE("TapWeights", [-0.1 0.8 -0.1], "Mode", 1, ...
    "SymbolTime", 100e-12, "SampleInterval", 6.25e-12, "WaveType", "Impulse");
impulseEq = ffe(impulseIn);

dfe = serdes.DFE("TapWeights", zeros(1,5), "Mode", 2, "WaveType", "Impulse", ...
    "SymbolTime", 100e-12, "SampleInterval", 6.25e-12);
