dfecdr = serdes.DFECDR("TapWeights", zeros(1,3), "Mode", 2, ...
    "SymbolTime", 100e-12, "SampleInterval", 6.25e-12, "WaveType", "Sample");
y = zeros(size(x));
for k = 1:numel(x)
    y(k) = dfecdr(x(k));
end

sat = serdes.SaturatingAmplifier("Limit", 0.6, "LinearGain", 2);
y = sat(linspace(-1, 1, 101)');
plot(y)

SymbolTime = 100e-12; N = 16; dt = SymbolTime/N;
channel = serdes.ChannelLoss("Loss", 10, "dt", dt, "TargetFrequency", 1/SymbolTime/2);
imp = channel.impulse;
pulse = impulse2pulse(imp, N, dt);

stim = serdes.Stimulus("Modulation", 4, "Order", 13, "SymbolTime", 100e-12, "SampleInterval", 6.25e-12);
x = zeros(16*1000, 1);
for k = 1:numel(x), x(k) = stim(); end
plot(x(1:400))

