ntf = synthesizeNTF(5, 32, 1, 1.5, 0);
[snr, amp] = predictSNR(ntf, 32);
plot(amp, snr); xlabel("Input level (dBFS)"); ylabel("SNR (dB)")

ntf = synthesizeNTF(4, 64, 1);
[a, g, b, c] = realizeNTF(ntf, "CIFB");
ABCD = stuffABCD(a, g, b, c, "CIFB");

N = 8192; fB = ceil(N/(2*64)); ftest = floor(fB/3);
u = 0.5*sin(2*pi*ftest/N*(0:N-1));
v = simulateDSM(u, ntf);
spec = fft(v .* hann(N)');
snr = calculateSNR(spec(1:fB), ftest)

[snrPred, amp] = predictSNR(ntf, 64);
[snrSim, ampSim] = simulateSNR(ntf, 64);
plot(amp, snrPred, ampSim, snrSim, "o")
